#include <iostream>
#include <string>
#include <algorithm>
#include <cmath>

int main() {
    int h, n;
    std::cin >> h >> n;
    int n_minus_one = n - 1;
    std::string bin_str = "";
    while (n_minus_one > 0) {
        bin_str = (char)((n_minus_one % 2) + '0') + bin_str;
        n_minus_one /= 2;
    }
    int len = bin_str.length();
    bin_str = std::string(h - len, '0') + bin_str;

    int sum_res = 0;
    bool current_flag = true;
    for (int idx = 0; idx < h; ++idx) {
        if (bin_str[idx] == (current_flag ? '1' : '0')) {
            sum_res += (int)pow(2, h - idx);
        } else {
            current_flag = !current_flag;
            sum_res += 1;
        }
    }
    std::cout << sum_res << std::endl;
    return 0;
}
